selector_to_html = {"a[href=\"#spike-deconvolution-tau\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Spike Deconvolution &amp; Tau<a class=\"headerlink\" href=\"#spike-deconvolution-tau\" title=\"Link to this heading\">#</a></h3><p>Most calcium imaging pipelines model neural activity as an exponential decay process following each spike, making \u03c4 (tau) a key hyperparameter.</p>", "a[href=\"#data-files\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Data Files<a class=\"headerlink\" href=\"#data-files\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#visualizing-grid-search-results\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Visualizing Grid Search Results<a class=\"headerlink\" href=\"#visualizing-grid-search-results\" title=\"Link to this heading\">#</a></h3><p>You can loop through the results using the saved <code class=\"docutils literal notranslate\"><span class=\"pre\">ops.npy</span></code> files:</p>", "a[href=\"#no-cells-detected\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">No Cells Detected<a class=\"headerlink\" href=\"#no-cells-detected\" title=\"Link to this heading\">#</a></h3><p><strong>Possible causes:</strong></p>", "a[href=\"#threshold-scaling-default-1-0\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">threshold_scaling</span></code> (default: 1.0)<a class=\"headerlink\" href=\"#threshold-scaling-default-1-0\" title=\"Link to this heading\">#</a></h4><p>Multiplier for detection threshold. <strong>Lower values detect more ROIs.</strong></p>", "a[href=\"#fig-threshold-scaling\"]": "<figure class=\"align-default\" id=\"fig-threshold-scaling\">\n<img alt=\"Effect of threshold_scaling on detected cells\" src=\"_images/default_params_thr.png\"/>\n<figcaption>\n<p><span class=\"caption-text\">Effect of varying <code class=\"docutils literal notranslate\"><span class=\"pre\">threshold_scaling</span></code> on detected cells. Notably, increasing this threshold actually led to several cells being detected that were not otherwise detected, and vice-versa.</span><a class=\"headerlink\" href=\"#fig-threshold-scaling\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#registration-parameters\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Registration Parameters<a class=\"headerlink\" href=\"#registration-parameters\" title=\"Link to this heading\">#</a></h3><p>We use <a class=\"reference external\" href=\"https://suite2p.readthedocs.io/en/latest/registration.html\">Suite2p Registration</a> to ensure spatial alignment across all frames in a movie. This means a neuron that appears in one location in frame 0 remains in the same spot in frame N.</p><p>Suite2p first runs rigid registration (frame-wide shifts using phase correlation), followed by optional non-rigid registration (local shifts in blocks).</p>", "a[href=\"#tau-default-1-0\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">tau</span></code> (default: 1.0)<a class=\"headerlink\" href=\"#tau-default-1-0\" title=\"Link to this heading\">#</a></h4><p>Calcium indicator decay time constant in seconds. <strong>Critical for binning and deconvolution.</strong></p><p>GCaMP expression is slow, often taking between 100 ms to over 1 second for the signal to rise and decay. This is the timescale of the sensor, in seconds. We need this value because one of the main performance optimizations is <a class=\"reference external\" href=\"https://en.wikipedia.org/wiki/Data_binning\">binning</a>. We can bin our data <strong>because of this slow timescale</strong> - we set the bin-size to our sensor\u2019s timescale because we expect all frames in this window to be the same (on average).</p>", "a[href=\"#rolling-percentile-baseline-recommended\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Rolling Percentile Baseline (Recommended)<a class=\"headerlink\" href=\"#rolling-percentile-baseline-recommended\" title=\"Link to this heading\">#</a></h4><p><strong>Window size rule of thumb:</strong> Use ~10\u00d7 the indicator decay time constant (tau) \u00d7 frame rate.\nFor example, with jGCaMP7s (tau\u22481.0s) at 30Hz: 10 \u00d7 1.0 \u00d7 30 = 300 frames.\nThis ensures the window spans multiple calcium transients so the percentile filter\ncan find the baseline between events. See <a class=\"reference external\" href=\"https://suite2p.readthedocs.io/en/latest/celldetection.html\">Suite2p Cell Detection</a> for related binning logic.</p><p><strong>When to use:</strong> Most datasets, handles slow baseline drifts.</p>", "a[href=\"#registration-grid-search\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Registration Grid Search<a class=\"headerlink\" href=\"#registration-grid-search\" title=\"Link to this heading\">#</a></h3><p>To evaluate what registration parameters you should use, you can try both enabling two-step registration and lowering the block-size for rigid registration.</p>", "a[href=\"#ug-fig-mean-enhanced\"]": "<figure class=\"align-default\" id=\"ug-fig-mean-enhanced\">\n<a class=\"reference internal image-reference\" href=\"_images/04_mean_enhanced.png\"><img alt=\"Enhanced Mean Image\" src=\"_images/04_mean_enhanced.png\" style=\"width: 50%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\"><strong>Enhanced mean image</strong> (<code class=\"docutils literal notranslate\"><span class=\"pre\">meanImgE</span></code>): a spatial high-pass of <code class=\"docutils literal notranslate\"><span class=\"pre\">meanImg</span></code> computed during registration, which sharpens cell boundaries. Shown in the GUI as \u201cE: mean img (enhanced)\u201d; it is not a Cellpose detection input.</span><a class=\"headerlink\" href=\"#ug-fig-mean-enhanced\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#anatomical-only-legacy-default-0\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">anatomical_only</span></code> (legacy, default: 0)<a class=\"headerlink\" href=\"#anatomical-only-legacy-default-0\" title=\"Link to this heading\">#</a></h4><p>The integer <code class=\"docutils literal notranslate\"><span class=\"pre\">anatomical_only</span></code> is still accepted and maps to <code class=\"docutils literal notranslate\"><span class=\"pre\">algorithm</span></code> / <code class=\"docutils literal notranslate\"><span class=\"pre\">img</span></code>:</p>", "a[href=\"#ug-fig-all-planes\"]": "<figure class=\"align-default\" id=\"ug-fig-all-planes\">\n<a class=\"reference internal image-reference\" href=\"_images/all_planes_masks.png\"><img alt=\"All Planes Masks\" src=\"_images/all_planes_masks.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\"><strong>ROI masks across all z-planes</strong> arranged in a grid. Each panel shows the enhanced mean image with segmentation overlay for one plane. Use this to quickly assess segmentation quality across the entire volume and identify planes with poor detection.</span><a class=\"headerlink\" href=\"#ug-fig-all-planes\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#spatial-hp-detect-default-25\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">spatial_hp_detect</span></code> (default: 25)<a class=\"headerlink\" href=\"#spatial-hp-detect-default-25\" title=\"Link to this heading\">#</a></h4><p>Gaussian filter size applied during functional cell detection to reduce background noise.</p><p>A good value for <code class=\"docutils literal notranslate\"><span class=\"pre\">spatial_hp_detect</span></code> will decrease the brightness of the background while increasing the contrast between background and neuron.</p>", "a[href=\"pipeline_comparison.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Pipeline Comparison<a class=\"headerlink\" href=\"#pipeline-comparison\" title=\"Link to this heading\">#</a></h1><p>This page compares how different calcium imaging analysis pipelines handle \u0394F/F calculation, neuropil correction, and spike deconvolution.</p>", "a[href=\"#ug-fig-max-proj\"]": "<figure class=\"align-default\" id=\"ug-fig-max-proj\">\n<a class=\"reference internal image-reference\" href=\"_images/02_max_projection.png\"><img alt=\"Maximum Intensity Projection\" src=\"_images/02_max_projection.png\" style=\"width: 50%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\"><strong>Maximum intensity projection</strong> (<code class=\"docutils literal notranslate\"><span class=\"pre\">max_proj</span></code>) computed as <code class=\"docutils literal notranslate\"><span class=\"pre\">mov_hp.max(axis=0)</span></code> from the temporally high-pass filtered registered movie. Highlights the brightest pixels over time, useful for identifying highly active regions and checking for motion artifacts. This is the image used for <code class=\"docutils literal notranslate\"><span class=\"pre\">img=\"max_proj\"</span></code>.</span><a class=\"headerlink\" href=\"#ug-fig-max-proj\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#reader-and-writer-kwargs\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Reader and Writer Kwargs<a class=\"headerlink\" href=\"#reader-and-writer-kwargs\" title=\"Link to this heading\">#</a></h3><p>When processing raw ScanImage TIFFs or other input formats, you may need to control how the data is read. The <code class=\"docutils literal notranslate\"><span class=\"pre\">reader_kwargs</span></code> parameter passes arguments directly to <code class=\"docutils literal notranslate\"><span class=\"pre\">mbo_utilities.imread()</span></code>.</p>", "a[href=\"#spatial-hp-cp-default-0\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">spatial_hp_cp</span></code> (default: 0)<a class=\"headerlink\" href=\"#spatial-hp-cp-default-0\" title=\"Link to this heading\">#</a></h4><p>Spatial high-pass applied to the chosen <code class=\"docutils literal notranslate\"><span class=\"pre\">img</span></code> before Cellpose (upstream <code class=\"docutils literal notranslate\"><span class=\"pre\">cellpose_settings.highpass_spatial</span></code>). Multiplies the cell diameter to set the Gaussian sigma; 0 disables it.</p>", "a[href=\"#indicator-dynamics\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Indicator Dynamics<a class=\"headerlink\" href=\"#indicator-dynamics\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#ug-fig-roi-3d\"]": "<figure class=\"align-default\" id=\"ug-fig-roi-3d\">\n<a class=\"reference internal image-reference\" href=\"_images/roi_map_3d.png\"><img alt=\"3D ROI Map\" src=\"_images/roi_map_3d.png\" style=\"width: 80%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\"><strong>3D scatter plot of ROI centroids</strong> with each point representing a detected cell. Points are colored by SNR (signal-to-noise ratio), revealing the spatial distribution of signal quality through the volume. Brighter colors indicate higher quality cells.</span><a class=\"headerlink\" href=\"#ug-fig-roi-3d\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#fig-default-params-subset\"]": "<figure class=\"align-default\" id=\"fig-default-params-subset\">\n<img alt=\"Zoomed view showing missed cells\" src=\"_images/default_parameters_subset.png\"/>\n<figcaption>\n<p><span class=\"caption-text\">Zoomed view showing several obvious cells that were not detected with default parameters.</span><a class=\"headerlink\" href=\"#fig-default-params-subset\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#allow-overlap-default-false\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">allow_overlap</span></code> (default: False)<a class=\"headerlink\" href=\"#allow-overlap-default-false\" title=\"Link to this heading\">#</a></h4><p>Whether ROIs can share pixels.</p>", "a[href=\"#inner-neuropil-radius-default-2\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">inner_neuropil_radius</span></code> (default: 2)<a class=\"headerlink\" href=\"#inner-neuropil-radius-default-2\" title=\"Link to this heading\">#</a></h4><p>Inner radius (pixels) of neuropil annulus around each ROI.</p>", "a[href=\"#planar-pipeline\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Planar Pipeline<a class=\"headerlink\" href=\"#planar-pipeline\" title=\"Link to this heading\">#</a></h2><p>For testing parameters or processing individual planes:</p>", "a[href=\"#diameter-default-0\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">diameter</span></code> (default: 0)<a class=\"headerlink\" href=\"#diameter-default-0\" title=\"Link to this heading\">#</a></h4><p>Expected cell diameter in pixels. <strong>Required for Cellpose</strong>.</p>", "a[href=\"glossary.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Glossary<a class=\"headerlink\" href=\"#glossary\" title=\"Link to this heading\">#</a></h1>", "a[href=\"#ug-fig-quality-diag\"]": "<figure class=\"align-default\" id=\"ug-fig-quality-diag\">\n<a class=\"reference internal image-reference\" href=\"_images/05_quality_diagnostics.png\"><img alt=\"Quality Diagnostics\" src=\"_images/05_quality_diagnostics.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\"><strong>ROI quality diagnostics</strong> showing:</span><a class=\"headerlink\" href=\"#ug-fig-quality-diag\" title=\"Link to this image\">#</a></p>\n<div class=\"legend\">\n<ul class=\"simple\">\n<li><p><strong>Size distribution</strong>: Histogram of ROI areas (pixels) for accepted vs rejected cells</p></li>\n<li><p><strong>SNR distribution</strong>: Signal-to-noise ratio for each ROI</p></li>\n<li><p><strong>Compactness</strong>: How circular each ROI is (1.0 = perfect circle)</p></li>\n<li><p><strong>Skewness</strong>: Positive skew indicates calcium transients</p></li>\n</ul>\n<p>Use these metrics to tune parameters like <code class=\"docutils literal notranslate\"><span class=\"pre\">max_overlap</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">threshold_scaling</span></code>, and post-hoc filters.</p>\n</div>\n</figcaption>\n</figure>", "a[href=\"#reader-options-for-raw-scanimage-tiffs\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Reader Options for Raw ScanImage TIFFs<a class=\"headerlink\" href=\"#reader-options-for-raw-scanimage-tiffs\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#troubleshooting\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Troubleshooting<a class=\"headerlink\" href=\"#troubleshooting\" title=\"Link to this heading\">#</a></h2><h3>No Cells Detected<a class=\"headerlink\" href=\"#no-cells-detected\" title=\"Link to this heading\">#</a></h3><p><strong>Possible causes:</strong></p>", "a[href=\"api.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">API<a class=\"headerlink\" href=\"#api\" title=\"Link to this heading\">#</a></h1><p>Functions, broken down by category.</p>", "a[href=\"#how-reference-images-are-computed\"]": "<h5 class=\"tippy-header\" style=\"margin-top: 0;\">How Reference Images Are Computed<a class=\"headerlink\" href=\"#how-reference-images-are-computed\" title=\"Link to this heading\">#</a></h5><p>During Suite2p detection, the registered movie undergoes temporal high-pass filtering to remove slow baseline fluctuations. This is done via <code class=\"docutils literal notranslate\"><span class=\"pre\">temporal_high_pass_filter(mov,</span> <span class=\"pre\">width=high_pass)</span></code> which subtracts either a Gaussian-filtered or rolling mean version of the movie over time.</p>", "a[href=\"#pipeline-basics\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Pipeline Basics<a class=\"headerlink\" href=\"#pipeline-basics\" title=\"Link to this heading\">#</a></h2><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">lsp.pipeline()</span></code> function is the recommended entry point for all processing. It automatically handles:</p>", "a[href=\"#maxregshift-default-0-1\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">maxregshift</span></code> (default: 0.1)<a class=\"headerlink\" href=\"#maxregshift-default-0-1\" title=\"Link to this heading\">#</a></h4><p>Maximum allowed registration shift as fraction of frame size.</p>", "a[href=\"#registration-artifacts\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Registration Artifacts<a class=\"headerlink\" href=\"#registration-artifacts\" title=\"Link to this heading\">#</a></h3><p><strong>Wobbling/warping at edges:</strong></p>", "a[href=\"#user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1><p>For</p>", "a[href=\"#post-processing-filters\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Post-Processing Filters<a class=\"headerlink\" href=\"#post-processing-filters\" title=\"Link to this heading\">#</a></h2><p>LBM-Suite2p-Python includes filters to refine cell selection after detection. These filters can remove ROIs based on size, shape, and activity metrics.</p>", "a[href=\"#ug-fig-traces-raw\"]": "<figure class=\"align-default\" id=\"ug-fig-traces-raw\">\n<a class=\"reference internal image-reference\" href=\"_images/07_traces_raw.png\"><img alt=\"Raw Fluorescence Traces\" src=\"_images/07_traces_raw.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\"><strong>Raw fluorescence traces</strong> for the top 20 neurons sorted by quality score. The y-axis shows fluorescence intensity (arbitrary units), x-axis shows time in seconds.</span><a class=\"headerlink\" href=\"#ug-fig-traces-raw\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#fig-max-overlap\"]": "<figure class=\"align-default\" id=\"fig-max-overlap\">\n<img alt=\"Effect of max_overlap on detected cells\" src=\"_images/default_parameters_max_overlap.png\"/>\n<figcaption>\n<p><span class=\"caption-text\">Effect of varying <code class=\"docutils literal notranslate\"><span class=\"pre\">max_overlap</span></code> on detected cells.</span><a class=\"headerlink\" href=\"#fig-max-overlap\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#quick-start-anatomical-detection\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Quick Start: Anatomical Detection<a class=\"headerlink\" href=\"#quick-start-anatomical-detection\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#ug-fig-traces-dff\"]": "<figure class=\"align-default\" id=\"ug-fig-traces-dff\">\n<a class=\"reference internal image-reference\" href=\"_images/08_traces_dff.png\"><img alt=\"\u0394F/F Traces\" src=\"_images/08_traces_dff.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\"><strong>\u0394F/F traces</strong> computed using rolling percentile baseline. These normalized traces are directly comparable across cells and experiments. The quality-sorted display surfaces the most reliable signals first.</span><a class=\"headerlink\" href=\"#ug-fig-traces-dff\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#critical-parameters\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Critical Parameters<a class=\"headerlink\" href=\"#critical-parameters\" title=\"Link to this heading\">#</a></h2><p>Understanding key Suite2p parameters is essential for good segmentation results.</p>", "a[href=\"#median-filter-baseline\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Median Filter Baseline<a class=\"headerlink\" href=\"#median-filter-baseline\" title=\"Link to this heading\">#</a></h4><p><strong>When to use:</strong> Quick baseline for stable recordings.</p>", "a[href=\"#examples\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Examples<a class=\"headerlink\" href=\"#examples\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#loading-results\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Loading Results<a class=\"headerlink\" href=\"#loading-results\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#extraction-parameters\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Extraction Parameters<a class=\"headerlink\" href=\"#extraction-parameters\" title=\"Link to this heading\">#</a></h3><h4><code class=\"docutils literal notranslate\"><span class=\"pre\">neucoeff</span></code> (default: 0.7)<a class=\"headerlink\" href=\"#neucoeff-default-0-7\" title=\"Link to this heading\">#</a></h4><p>Neuropil subtraction coefficient for deconvolution.</p>", "a[href=\"#max-overlap-default-0-75\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">max_overlap</span></code> (default: 0.75)<a class=\"headerlink\" href=\"#max-overlap-default-0-75\" title=\"Link to this heading\">#</a></h4><p>Maximum allowed spatial overlap between ROIs (0-1). If two masks overlap by a fraction &gt; max_overlap, they will be discarded/rejected.</p>", "a[href=\"#understanding-ff-traces\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Activity \u0394F/F Traces<a class=\"headerlink\" href=\"#activity-f-f-traces\" title=\"Link to this heading\">#</a></h4><p>The \u0394F/F (delta F over F) traces in <code class=\"docutils literal notranslate\"><span class=\"pre\">08_traces_dff.png</span></code> show the change in fluorescence normalized by baseline. This is the standard metric for comparing neural activity across cells and experiments.</p><p><strong>Window Size Selection for \u0394F/F:</strong></p>", "a[href=\"#fig-spatial-hp\"]": "<figure class=\"align-default\" id=\"fig-spatial-hp\">\n<img alt=\"Effect of spatial_hp_detect on detected cells\" src=\"_images/default_parameters_spatial_hp_detect.png\"/>\n<figcaption>\n<p><span class=\"caption-text\">Effect of varying <code class=\"docutils literal notranslate\"><span class=\"pre\">spatial_hp_detect</span></code> on detected cells.</span><a class=\"headerlink\" href=\"#fig-spatial-hp\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#volumetric-outputs\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Volumetric Outputs<a class=\"headerlink\" href=\"#volumetric-outputs\" title=\"Link to this heading\">#</a></h3><p>When processing multiple planes with <code class=\"docutils literal notranslate\"><span class=\"pre\">lsp.pipeline()</span></code>, additional files are generated in the root save directory:</p>", "a[href=\"#functional-detection-parameters\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Functional Detection Parameters<a class=\"headerlink\" href=\"#functional-detection-parameters\" title=\"Link to this heading\">#</a></h3><p>For datasets where anatomical detection doesn\u2019t work well, or when you need activity-based ROI detection, use functional parameters.</p>", "a[href=\"#anatomical-segmentation-cellpose-recommended\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Anatomical Segmentation (Cellpose) - Recommended<a class=\"headerlink\" href=\"#anatomical-segmentation-cellpose-recommended\" title=\"Link to this heading\">#</a></h3><p>Anatomical segmentation uses <a class=\"reference external\" href=\"https://www.cellpose.org/\">Cellpose</a> to detect cell bodies based on morphology rather than functional activity. This is the recommended approach for LBM data.</p>", "a[href=\"#planar-outputs\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Planar Outputs<a class=\"headerlink\" href=\"#planar-outputs\" title=\"Link to this heading\">#</a></h3><p>Each z-plane directory contains:</p>", "a[href=\"#shot-noise-levels\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Shot Noise Levels<a class=\"headerlink\" href=\"#shot-noise-levels\" title=\"Link to this heading\">#</a></h4><p>The noise histograms (<code class=\"docutils literal notranslate\"><span class=\"pre\">10_noise_accepted.png</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">11_noise_rejected.png</span></code>) show <strong>standardized shot noise levels</strong> for each ROI. This metric helps you:</p>", "a[href=\"#f-f-calculation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u0394F/F Calculation<a class=\"headerlink\" href=\"#f-f-calculation\" title=\"Link to this heading\">#</a></h2><p>The gold-standard formula for measuring cellular activity is \u0394F/F\u2080 (delta F over F naught), which normalizes fluorescence change by baseline:</p>", "a[href=\"#writer-options\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Writer Options<a class=\"headerlink\" href=\"#writer-options\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#pipeline-parameters\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Pipeline Parameters<a class=\"headerlink\" href=\"#pipeline-parameters\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#volumetric-pipeline\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Volumetric Pipeline<a class=\"headerlink\" href=\"#volumetric-pipeline\" title=\"Link to this heading\">#</a></h2><p>Instead of a single file, provide a list of z-planes or a directory:</p>", "a[href=\"#registration-metrics-ops-regdx\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Registration Metrics (<code class=\"docutils literal notranslate\"><span class=\"pre\">ops['regDX']</span></code>)<a class=\"headerlink\" href=\"#registration-metrics-ops-regdx\" title=\"Link to this heading\">#</a></h4><p>Suite2p computes PC-based metrics to assess registration quality:</p>", "a[href=\"#orthogonal-slices\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Orthogonal Slices<a class=\"headerlink\" href=\"#orthogonal-slices\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#align-by-chan-default-1\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">align_by_chan</span></code> (default: 1)<a class=\"headerlink\" href=\"#align-by-chan-default-1\" title=\"Link to this heading\">#</a></h4><p>Which channel to use for registration (1-based indexing):</p>", "a[href=\"#registration-quality-metrics\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Registration Quality Metrics<a class=\"headerlink\" href=\"#registration-quality-metrics\" title=\"Link to this heading\">#</a></h3><p><strong>Requires at least 1500 frames per plane</strong></p><p>Each plane directory contains PC-based registration quality metrics in <code class=\"docutils literal notranslate\"><span class=\"pre\">pc_metrics/</span></code>:</p>", "a[href=\"#rastermap-volume-wide\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Rastermap (Volume-wide)<a class=\"headerlink\" href=\"#rastermap-volume-wide\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#overwriting-results\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Overwriting results<a class=\"headerlink\" href=\"#overwriting-results\" title=\"Link to this heading\">#</a></h3><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">force_reg</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">force_detect</span></code> flags control whether to re-run processing when results already exist. This table shows the behavior for all combinations:</p><p><strong>Overwrite registration</strong></p>", "a[href=\"#trace-quality-sorting\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Trace Quality Sorting<a class=\"headerlink\" href=\"#trace-quality-sorting\" title=\"Link to this heading\">#</a></h4><p>The trace plots (<code class=\"docutils literal notranslate\"><span class=\"pre\">07_traces_raw.png</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">08_traces_dff.png</span></code>) display the <strong>top 20 neurons sorted by quality score</strong>.\nThis weighted score combines three metrics to surface the best traces:</p>", "a[href=\"#shot-noise-estimation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Shot Noise Estimation<a class=\"headerlink\" href=\"#shot-noise-estimation\" title=\"Link to this heading\">#</a></h4><p>Quantifies SNR for comparing across datasets.</p>", "a[href=\"#neucoeff-default-0-7\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">neucoeff</span></code> (default: 0.7)<a class=\"headerlink\" href=\"#neucoeff-default-0-7\" title=\"Link to this heading\">#</a></h4><p>Neuropil subtraction coefficient for deconvolution.</p>", "a[href=\"#do-registration-default-1\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">do_registration</span></code> (default: 1)<a class=\"headerlink\" href=\"#do-registration-default-1\" title=\"Link to this heading\">#</a></h4><p>Controls whether to run registration:</p>", "a[href=\"#further-reading\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Further Reading<a class=\"headerlink\" href=\"#further-reading\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#visual-parameter-comparisons\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Visual Parameter Comparisons<a class=\"headerlink\" href=\"#visual-parameter-comparisons\" title=\"Link to this heading\">#</a></h4><p>To see the effect of each parameter on segmentation results, it\u2019s helpful to start with default parameters as a baseline.</p>", "a[href=\"#input-formats\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Input formats<a class=\"headerlink\" href=\"#input-formats\" title=\"Link to this heading\">#</a></h2><p>The pipeline accepts all filetypes at <a class=\"reference external\" href=\"https://millerbrainobservatory.github.io/mbo_utilities/array_types.html\">mbo_utilities imread()</a> accepts.</p>", "a[href=\"#fig-default-params\"]": "<figure class=\"align-default\" id=\"fig-default-params\">\n<img alt=\"Default parameter segmentation results\" src=\"_images/default_parameters.png\"/>\n<figcaption>\n<p><span class=\"caption-text\">Default parameters yield <strong>324</strong> accepted and <strong>737</strong> rejected neurons.</span><a class=\"headerlink\" href=\"#fig-default-params\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#setting-ops-flat-or-suite2p-s-nested-settings\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Setting ops: flat or suite2p\u2019s nested settings<a class=\"headerlink\" href=\"#setting-ops-flat-or-suite2p-s-nested-settings\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">ops</span></code> is a <strong>flat dict</strong> \u2014 the fork\u2019s convention and what <code class=\"docutils literal notranslate\"><span class=\"pre\">lsp.default_ops()</span></code> returns.\nYou can also pass suite2p\u2019s newer <strong>nested</strong> <code class=\"docutils literal notranslate\"><span class=\"pre\">db</span></code> / <code class=\"docutils literal notranslate\"><span class=\"pre\">settings</span></code> dicts; they are flattened\nand merged into <code class=\"docutils literal notranslate\"><span class=\"pre\">ops</span></code> (explicit <code class=\"docutils literal notranslate\"><span class=\"pre\">ops</span></code> keys win). Both reach suite2p the same way, so use\nwhichever you have.</p>", "a[href=\"#ug-fig-vol-trace\"]": "<figure class=\"align-default\" id=\"ug-fig-vol-trace\">\n<a class=\"reference internal image-reference\" href=\"_images/volume_trace_analysis.png\"><img alt=\"Volume Trace Analysis\" src=\"_images/volume_trace_analysis.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\"><strong>Volume-wide trace analysis</strong> combining multiple views:</span><a class=\"headerlink\" href=\"#ug-fig-vol-trace\" title=\"Link to this image\">#</a></p>\n<div class=\"legend\">\n<ul class=\"simple\">\n<li><p><strong>Left</strong>: Example \u0394F/F traces from representative cells across planes</p></li>\n<li><p><strong>Middle</strong>: SNR and mean fluorescence as a function of z-depth</p></li>\n<li><p><strong>Right</strong>: Activity heatmap showing temporal patterns across all cells</p></li>\n</ul>\n<p>This visualization helps identify depth-dependent signal quality and synchronized activity patterns.</p>\n</div>\n</figcaption>\n</figure>", "a[href=\"#nonrigid-default-true\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">nonrigid</span></code> (default: True)<a class=\"headerlink\" href=\"#nonrigid-default-true\" title=\"Link to this heading\">#</a></h4><p>Use block-wise non-rigid registration to handle local motion.</p>", "a[href=\"#activity-f-f-traces\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Activity \u0394F/F Traces<a class=\"headerlink\" href=\"#activity-f-f-traces\" title=\"Link to this heading\">#</a></h4><p>The \u0394F/F (delta F over F) traces in <code class=\"docutils literal notranslate\"><span class=\"pre\">08_traces_dff.png</span></code> show the change in fluorescence normalized by baseline. This is the standard metric for comparing neural activity across cells and experiments.</p><p><strong>Window Size Selection for \u0394F/F:</strong></p>", "a[href=\"#multi-roi-processing\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-ROI Processing<a class=\"headerlink\" href=\"#multi-roi-processing\" title=\"Link to this heading\">#</a></h2><p>LBM-Suite2p-Python automatically detects and merges ScanImage multi-ROI acquisitions.</p><p><strong>Automatic detection:</strong> If \u201croi\u201d appears in filename (case-insensitive), merging is triggered.</p>", "a[href=\"#ug-fig-rastermap-vol\"]": "<figure class=\"align-default\" id=\"ug-fig-rastermap-vol\">\n<a class=\"reference internal image-reference\" href=\"_images/rastermap.png\"><img alt=\"Rastermap\" src=\"_images/rastermap.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\"><strong>Activity sorted by similarity</strong> using the <a class=\"reference external\" href=\"https://github.com/MouseLand/rastermap\">Rastermap</a> algorithm. Cells from all planes are combined and reordered so that neurons with similar activity patterns appear adjacent. This reveals functional clusters and population dynamics that may span multiple z-planes.</span><a class=\"headerlink\" href=\"#ug-fig-rastermap-vol\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"postprocessing.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Postprocessing Functions<a class=\"headerlink\" href=\"#postprocessing-functions\" title=\"Link to this heading\">#</a></h1><p>This guide covers the postprocessing functions available in LBM-Suite2p-Python for analyzing and refining calcium imaging traces after Suite2p extraction.</p>", "a[href=\"#visualization-files\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Visualization Files<a class=\"headerlink\" href=\"#visualization-files\" title=\"Link to this heading\">#</a></h4><p>Files are numbered to ensure proper ordering when viewing in file browsers.</p>", "a[href=\"#d-roi-map\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">3D ROI Map<a class=\"headerlink\" href=\"#d-roi-map\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#volume-trace-analysis\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Volume Trace Analysis<a class=\"headerlink\" href=\"#volume-trace-analysis\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#ug-fig-orthoslices\"]": "<figure class=\"align-default\" id=\"ug-fig-orthoslices\">\n<a class=\"reference internal image-reference\" href=\"_images/orthoslices.png\"><img alt=\"Orthoslices\" src=\"_images/orthoslices.png\" style=\"width: 80%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\"><strong>Orthogonal slices</strong> through the mean intensity volume. Shows XY (axial), XZ (coronal), and YZ (sagittal) views with crosshairs indicating the slice positions. Useful for verifying volume alignment and identifying depth-dependent signal changes.</span><a class=\"headerlink\" href=\"#ug-fig-orthoslices\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#ug-fig-segmentation\"]": "<figure class=\"align-default\" id=\"ug-fig-segmentation\">\n<a class=\"reference internal image-reference\" href=\"_images/04_mean_enhanced_segmentation.png\"><img alt=\"Segmentation Overlay\" src=\"_images/04_mean_enhanced_segmentation.png\" style=\"width: 50%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\"><strong>Segmentation overlay</strong> on the enhanced mean image. Accepted ROIs are shown as colored outlines. Use this to visually verify that detected cells match actual cell bodies.</span><a class=\"headerlink\" href=\"#ug-fig-segmentation\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#f-f-parameters\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u0394F/F Parameters<a class=\"headerlink\" href=\"#f-f-parameters\" title=\"Link to this heading\">#</a></h3><h4>Rolling Percentile Baseline (Recommended)<a class=\"headerlink\" href=\"#rolling-percentile-baseline-recommended\" title=\"Link to this heading\">#</a></h4><p><strong>Window size rule of thumb:</strong> Use ~10\u00d7 the indicator decay time constant (tau) \u00d7 frame rate.\nFor example, with jGCaMP7s (tau\u22481.0s) at 30Hz: 10 \u00d7 1.0 \u00d7 30 = 300 frames.\nThis ensures the window spans multiple calcium transients so the percentile filter\ncan find the baseline between events. See <a class=\"reference external\" href=\"https://suite2p.readthedocs.io/en/latest/celldetection.html\">Suite2p Cell Detection</a> for related binning logic.</p><p><strong>When to use:</strong> Most datasets, handles slow baseline drifts.</p>", "a[href=\"#flow-threshold-default-0-4\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">flow_threshold</span></code> (default: 0.4)<a class=\"headerlink\" href=\"#flow-threshold-default-0-4\" title=\"Link to this heading\">#</a></h4><p>Maximum Cellpose flow error allowed for a mask. Higher values keep more (lower-quality) ROIs.</p>", "a[href=\"#cellprob-threshold-default-0-0\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">cellprob_threshold</span></code> (default: 0.0)<a class=\"headerlink\" href=\"#cellprob-threshold-default-0-0\" title=\"Link to this heading\">#</a></h4><p>Probability threshold from Cellpose output to determine cell boundaries. More negative values include more pixels.</p>", "a[href=\"#parameter-grid-search\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Parameter Grid Search<a class=\"headerlink\" href=\"#parameter-grid-search\" title=\"Link to this heading\">#</a></h2><p>Test multiple parameter combinations systematically. When tuning segmentation parameters, the easiest knobs to turn are <code class=\"docutils literal notranslate\"><span class=\"pre\">threshold_scaling</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">max_overlap</span></code>. Lower <code class=\"docutils literal notranslate\"><span class=\"pre\">threshold_scaling</span></code> \u2192 more candidate ROIs. Higher <code class=\"docutils literal notranslate\"><span class=\"pre\">max_overlap</span></code> \u2192 more overlapping ROIs are kept. But their effects aren\u2019t linear or always intuitive, so it\u2019s often best to <strong>grid search</strong> them.</p>", "a[href=\"#reference-images\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Reference Images<a class=\"headerlink\" href=\"#reference-images\" title=\"Link to this heading\">#</a></h4><p>The pipeline generates several reference images that serve as both quality checks and visualization aids. Each is computed from the registered movie at a different stage.</p>", "a[href=\"#algorithm-default-sparsery-and-img-default-max-proj-meanimg\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">algorithm</span></code> (default: <code class=\"docutils literal notranslate\"><span class=\"pre\">\"sparsery\"</span></code>) and <code class=\"docutils literal notranslate\"><span class=\"pre\">img</span></code> (default: <code class=\"docutils literal notranslate\"><span class=\"pre\">\"max_proj</span> <span class=\"pre\">/</span> <span class=\"pre\">meanImg\"</span></code>)<a class=\"headerlink\" href=\"#algorithm-default-sparsery-and-img-default-max-proj-meanimg\" title=\"Link to this heading\">#</a></h4><p>Set <code class=\"docutils literal notranslate\"><span class=\"pre\">algorithm=\"cellpose\"</span></code> to enable anatomical detection, then choose the image Cellpose segments with <code class=\"docutils literal notranslate\"><span class=\"pre\">img</span></code>:</p>", "a[href=\"#quality-diagnostics\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Quality Diagnostics<a class=\"headerlink\" href=\"#quality-diagnostics\" title=\"Link to this heading\">#</a></h4><p>The quality diagnostics panel provides a multi-metric view of ROI quality:</p>", "a[href=\"#fluorescence-traces\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Fluorescence Traces<a class=\"headerlink\" href=\"#fluorescence-traces\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#fig-tau-effect\"]": "<figure class=\"align-default\" id=\"fig-tau-effect\">\n<img alt=\"Effect of tau on detected cells\" src=\"_images/default_parameters_tau.png\"/>\n<figcaption>\n<p><span class=\"caption-text\">Effect of varying <code class=\"docutils literal notranslate\"><span class=\"pre\">tau</span></code> on segmentation results. Changing tau has a dramatic influence on detection.</span><a class=\"headerlink\" href=\"#fig-tau-effect\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#segmentation-overlays\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Segmentation Overlays<a class=\"headerlink\" href=\"#segmentation-overlays\" title=\"Link to this heading\">#</a></h4><p>Each reference image has a corresponding segmentation overlay showing detected ROIs:</p>", "a[href=\"#all-planes-masks\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">All Planes Masks<a class=\"headerlink\" href=\"#all-planes-masks\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#registration-output-files\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Registration Output Files<a class=\"headerlink\" href=\"#registration-output-files\" title=\"Link to this heading\">#</a></h4><p>Registration produces these files in addition to the main outputs:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
